    def bfs(r, c):
        queue, nodes = [(r, c)], set([(r, c)])
        while queue:
            x, y = queue.pop(0)
            for i, j in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                if 0 <= i < n and 0 <= j < n and grid[i][j] == '.' and (i, j) not in nodes:
                    nodes.add((i, j))
                    queue.append((i, j))
        visited = set()
        while nodes:
            x, y = nodes.pop()
            visited.add((x, y))
            for i, j in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                if 0 <= i < n and 0 <= j < n and grid[i][j] == '.' and (i, j) not in visited:
                    bfs(i, j)
        return sum(1 for x, y in grid if (x, y) in visited)

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                max_size = max(max_size, bfs(i, j))
    return max_size * k

