from collections import deque

def bfs(grid, start):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([start])
    visited = set([start])

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return len(visited)

def max_connected_component(grid, k):
    rows, cols = len(grid), len(grid[0])
    def max_component_size_from_start(start):
        return bfs(grid, start)

    max_size = 0
    for r in range(rows):
        for c in range(cols):
            size_for_start = max_component_size_from_start((r, c))
            if 0 <= r - k <= rows and 0 <= c - k <= cols:
                size_for_start -= len(bfs(grid, (r - k, c - k)))
            if 0 <= r + k <= rows - k + 1 and 0 <= c + k <= cols - k + 1:
                size_for_start -= bfs(grid, (r + k, c + k))
            max_size = max(max_size, size_for_start)

    return max_size

