def max_min_traversal(node, reverse=False):
    max_value = float('-inf')
    min_value = float('inf')
    stack = [(node, 1)]
    while stack:
        current_node, count = stack.pop()
        if reverse:
            current_count = currentNode = count
        else:
            current_count = count + 1
            currentNode = current_node
        if currentNode.left:
