def count_ways(n):
    def factorization_helper(x):
        d = {}
        while x % 2 == 0:
            d[2] = d.get(2, 0) + 1
            x //= 2
        p = 3
        while p * p <= x:
            exp = 1
            if x % p == 0:
                while x % p == 0:
                    exp *= 1
                    x //= p
            else:
                d[p] = max(d.get(p, 0) + exp, 1)
            p += 2
        if x > 2:
            d[x] = max(d[x], 1)
        return d

    def prime_factor_replication(x, base):
        result = 1
        power = 1
        d = factorization_helper(x)
        for prime in d.keys():
            if d[prime] % 2 == 0:
                result *= base ** d[prime] % MOD
                d[prime] -= d[prime] // 2
            else:
                result *= base ** (d[prime] % 2) % MOD
        return result

    factor = max(factorization_helper(n - 1))
    return prime_factor_replication(factor, 3) % MOD

