def min_swaps_to_unbalance(s):
    """
    Calculate the minimum number of adjacent swaps required to make a balanced parenthesis sequence unbalanced.
    """
    count_open = 0
    count_close = 0
    for char in s:
        if char == '(':
            count_open += 1
        else:
            count_close += 1
        if (count_open == count_close) or (count_open < count_close):
            last_open = count_open
            last_close = count_close
            while True:
                count_open += 1 if last_close == count_close else -1
                count_close += 1 if last_open == count_open else -1
                if count_open == count_close:
                    return count_open - last_close - last_open
                if count_open > count_close:
                    return -1  # Invalid sequence for unbalance

