        graph = list(map(int, input().strip().split()))
        edge = input().strip().split()

        for s, g in enumerate(edge):
            graph[s + n] = [n - 1 if g == "-1 1 2" else g,
                            map(int, g.split()[1:])]

        # Perform topological sort
        visited = [False] * n
        parents = [0] * n
        roots = [False] * n

        def dfs(node):
            if not visited[node]:
                visited[node] = True
                for child in sorted(graph[node]):
                    if (graph[node][child] == "2"):
                        parents[child] += 1
                    else:
                        parents[child] += 0
                    dfs(child)

        root_val = 0
        for i in range(n):
            if not visited[i]:
                dfs(i)

        for parent in range(n):
            if graph[parent][0] == "1" or not graph[parent][1][0]:
                root_val += parents[parent]

        max_score = max(root_val, max_score)

