def min_swaps_to_unbalance_sequence():
    t = int(input().strip())
    for _ in range(t):
        s = input().strip()
        open_paren_index = s.find('(')
        close_paren_index = s.rfind(')')
        swap_count = 0

        while open_paren_index != -1 and close_paren_index != -1 and open_paren_index < close_paren_index:
            start = open_paren_index
            end = (open_paren_index + 1) % len(s)

            while start < len(s):
                if start != end:
                    if s[start] == '(':
                        end = (start + 1) % len(s)
                    else:
                        end = (start + len(s) - 1) % len(s)

                if s[start] == '(':
                    end = (start + open_paren_index + 1 - compare(open_paren_index, end)) % len(s)
                start = (start + compare(start, end)) % len(s)

                if start == end:
                    break

            if start == end:
                endIndex = start
            else:
                endIndex = end

            close_paren_index += endIndex
            if s[endIndex] == ')':
                # If a close paren was encountered and it's not yet the correct close paren index
                if end != endIndex:
                    # Add the number of correct closes to ends to account for the new end
                    swap_count += (len(s) - endIndex) - len(s[open_paren_index:])
                # Overwrite the close paren index with the correct end positions
                close_paren_index = startIndex = end
                end = (open_paren_index + 1 - compare(end, start)) % len(s)
                continue
            else:
                # swap substrings and capture additional correct closes at end
                swap_count += len(s[start:endIndex + 1]) - len(s[start]) + (endIndex - startIndex + 1)
                # Overwrite the end index with the modifies end starting at startIndex
                close_paren_index = startIndex = end

        print(swap_count)

