import heapq

def min_spreading_time(n, m, a, b, edges):
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def dijkstra(start, end):
        dist = [float('inf')] * (n + 1)
        dist[start] = 0
        pq = [(0, start)]
        while pq:
            d, u = heapq.heappop(pq)
            if u == end:
                return dist[end]
            for v, w in graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(pq, (dist[v], v))
        return dist[end]

    min_spanning_tree = []
    done = [False] * (n + 1)
    set_track = [(n, 10**7)]

    while set_track:
        n_set, current = heapq.heappop(set_track)
        if done[n_set]:
            continue
        done[n_set] = True
        for v, w in graph[n_set]:
            if not done[v] and (w == a or w == b):
                min_spanning_tree.append((v, w))
                if not done[v]:
                    heapq.heappush(set_track, (v, w))

    total_time = 0
    for start, end, time in min_spanning_tree:
        total_time += time

    return total_time

