def min_burles_to_prevent_assignment(n, s):
    stacked_instructions = []
    assignment_cost = 0
    forbidden_value = 0 if s == 0 else s
    budget = 0

    for _ in range(n):
        line = input().split()
        line_type = line[0]

        if line_type == "set":
            source, value = map(int, line[1:])
            if source == forbidden_value and budget > 0:
                assignment_cost += max(1 + assignment_cost, 0)
            elif source != forbidden_value:
                budget += value

        if line_type == "if":
            end_index = line.find("end")
            instruction_index = line.rfind("if", 2, end_index)

            if end_index == -1 or instruction_index == -1:
                line = line[:instruction_index + 1] + "end"
                instruction = line.strip()
            else:
                line = line[:instruction_index + 1] + "end" + line[instruction_index + 1:]

            offset_before_end = len(line) - len(line.rsplit("end", 1)[1]) - 1
            for _ in range(end_index - (offset_before_end)):
                line += " "

            line += input().strip()
            stripped_line = line[:offset_before_end].replace(" ", "")

            end_index = stripped_line.rfind("end")
            if stripped_line[0:instruction_index + 2] == "end if":
                budget += offset_before_end - 2 + max(assignment_cost + 1 + budget, offset_before_end + 1 + 1 + budget)
                assignment_cost += 1 + budget
            elif stripped_line[end_index] == ")":
                budget += 1 + max(assignment_cost, 1 + budget)
        elif line_type == "end":
            budget += max(assignment_cost, 1 + budget)

    return budget

