from functools import lru_cache

def count_ways(n):
    mod = 10**9 + 7
    matrix = [[0] * n for _ in range(n)]

    for _ in range(n-1):
        x, y = 1, 1

        if x == n - 1:
            x = 0

        if y == n - 1:
            y = 0

        if x > 0 and y > 0:
            matrix[x][y] = 1

        x -= 1
        y -= 1

    @lru_cache(None)
    def dfs(i, j):
        if i == n-1:
            return 1

        total = 0

        for k in range(n):
            if k != i and matrix[j][k]:
                total += dfs(i + 1, k)

        return total % mod

    return dfs(0, 0)

