    n = len(grid)
    size = 0

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.' and not ((i >= k and (j >= k - 1 and grid[i - k][j] == '.')) or (i < n - k and (j >= k - 1 and grid[i + k][j] == '.'))):
                visited = defaultdict(lambda: False)
                q = helper(i, j, k, visited)
                if q:
                    size += k * k + len(q)

