import collections

def min_burles_to_avoid_s(n, s, lines):
    if n == 0:
        if s == 0:
            return 0
        else:
            return 1

    pow_burles = 1
    wei = 1
    tree = collections.deque()
    line_no = 0

    while line_no < n:
        if pow_burles >= s:
            power_ans = pow_burles
            tree.appendleft((power_ans, wei))
            wei *= 2
            pow_burles //= 2
        if lines[line_no] == 'end':
            if line_no == 0:
                power_ans = pow_burles*2
            else:
                prev = tree.popleft()[0]
                if prev == power_ans:
                    power_ans = prev + wer[0]
                else:
                    power_ans = prev+wer[1]
            tree.appendleft((power_ans, wei))
            wei *= 2
            pow_burles //= 2
        elif lines[line_no] == 'if':
            pow_burles *= 2
            wei *= 2
            tree.appendleft((pow_burles, n))
        elif lines[line_no] == 'end':
            pass
        else:
            y = int(lines[line_no][4:6])
            v = int(lines[line_no][8:])
            tree.appendleft((v, (wei-6) % n+1))
        line_no += 1

    min_take = 0
    maxi = pow_burles
    while tree and tree[0][0] < maxi:
        if tree[0][0] != tree[0][0]:
            min_take += tree[0][0]
        tree.popleft()

    return min_take
