def max_community_rating(n, ratings):
    dp = [0] * (n + 1)
    max_rating = 0

    for i in range(1, n + 1):
        current_rating = dp[i-1]
        dp[i] = current_rating

        if ratings[i-1] > current_rating:
            dp[i] = current_rating + 1

        if ratings[i-1] < current_rating:
            dp[i] = max(dp[i], current_rating - 1)

        if ratings[i-1] == current_rating:
            dp[i] = max(dp[i], current_rating)

        if ratings[i-1] not in dp[:i]:
            dp[i] = dp[i] + 1
        elif ratings[i-1] < dp[i]:
            dp[i] = dp[i]

        max_rating = max(max_rating, dp[i])

    return max_rating

