import sys

def min_modulus(n, k, numbers):
    # Calculate the sum of numbers and their product
    total_sum = sum(numbers)
    product = reduce(lambda x, y: x * y, numbers)

    # Check if all numbers are equal
    if len(set(numbers)) == 1:
        return 0

    # Calculate the minimum modulus
    min_modulus = max(numbers) ** 2
    for i in range(2, min_modulus + 1):
        if total_sum % i != 0 and product % i != 0:
            continue
        for j in range(1, n + 1):
            if min(Mod(i, k, numbers), Mod(total_sum - i, k, numbers), Mod(product, k, numbers), Mod(product - numbers[j], k, numbers)) < (i + j - 1) * (n - j + 1) // 2:
                return i

    return min_modulus

def Mod(x, k, numbers):
    modulus = {}
    for num in numbers:
        if num in modulus:
            modulus[num] += x
        else:
            modulus[num] = x

    max_mod = max(modulus.keys())

    divisible = True
    for mod in modulus:
        if modulus[mod] % k != 0:
            divisible = False
            break

    return modulus[max_mod] if divisible else max_mod

