from math import gcd

def lcm(a, b):
    """Least common multiple of a and b"""
    return a * b // gcd(a, b)

def find_merging_threshold(n, k, nums):
    """
    Finds the minimum modular m (m > 0) such that for every pair of remaining integers (ai, aj),
    the inequality |(ai / nums[j]) - (aj / nums[j])| < m holds.

    Parameters:
    n (int): The number of distinct integers.
    k (int): The maximum number of integers to keep.
    nums (list of int): The list of distinct integers.

    Returns:
    int: The minimum modular m.
    """
    if k == 0:
        return max(nums)

    lcm_values = sorted(lcm(nums.pop(0), nums.pop(0)))
    for num in nums:
        lcm_values = sorted([lcm(x, num) for x in lcm_values])

    merged_count = 0
    stored_lcm = 0

    first = False
    for lcm in lcm_values:
        if not first and k > 0:
            first = True
            merged_count += 1
            stored_lcm = lcm

        if k == merged_count:
            break

    if first:
        return lcm // max(nums)
    else:
        return lcm

def is_valid_mangement_threshold(m, exist_num, increase_nums, decrease_nums):
    """
    Checks if all the inequalities hold for a given m.
    """
    for decrease_data in decrease_nums:
        for increase_data in increase_nums:
            if (lcm(increase_data, decrease_data) % m >= m / 2):
                return False
    return True

def minimum_merging_threshold(exist_num, k, increase_nums, decrease_nums):
    """
    Finds the minimum m such that the validity of all inequalities for merged decreased and increased inputs holds.
    """
    lower_limit = 1
    upper_limit = max(exist_num, max(increase_nums)) * 2
    s = (lower_limit % 2 == 0) * lower_limit + upper_limit // 2
    e = upper_limit // 2
    for i in range(s, e + 1):
        if is_valid_mangement_threshold(i, exist_num, increase_nums, decrease_nums):
            return i

    return upper_limit

