import sys

class Permutation:
    def __init__(self, p):
        self.p = p
        self.index = []
        for i in range(len(p)):
            self.index.append((p[i], i))

    def remove_max(self):
        if not self.index:
            return None
        max_elem = max(self.index, key=lambda x: x[0])[0]
        for i in sorted(self.index, key=lambda x: x[0], reverse=True):
            if i != max_elem:
                self.index.remove(i)
                break
        return max_elem

def main():
