from collections import defaultdict

def calculate_beauty(sequence):
    # Count how many beauties are needed for each possible view
    perspectives = [[0]*len(sequence) for _ in range((len(sequence)+2)//3)]
    views = defaultdict(int)
    for index in range(len(sequence)//3):
        views[3*index+1] -= 1
        views[3*index+2] -= 1
        views[3*index+3] -= 1
    for num_views in range(3*(len(sequence)//3)+2, len(sequence)+1, 3):
        views[num_views-1] += 1
        views[num_views-3] += 1
        views[num_views-2] += 1
        max_view = max(views.values())
        for value in views.values():
            if value == max_view:
                perspectives[value].append((3*index, index, num_views-3-index))
                positions[num_views-3-index] = True
                break
    return perspectives, views

def answer_question(sequence, q, queries):
    perspectives, _ = calculate_beauty(sequence)
    considered_beauty = {}
    for index in range(len(queries)):
        considered_beauty[queries[index]] = None
    for query in queries:
        beauty_range = perspectives[sequence[query[0]-1]][sequence[query[1]-1]-1]
        count = 0
        for start_row, start_column, end_column in beauty_range:
            for i in range(start_column, end_column):
                considered_beauty[query] = i + 1 if considered_beauty[query] is None else min(considered_beauty[query], i+1)
                for start in range(start_row-1, start_row+2):
                    for column in range(start+1, end_column+1):
                        if considered_beauty[query] is None or column != start:
                            count += perspectives[start][column-1]
                        elif considered_beauty[query] < column:
                            count += 1
                        elif considered_beauty[query] > column:
                            break
        considered_beauty[query] -= count
    return considered_beauty

