def print_result(n, k, grid):
    max_size = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.' and j + k < n:
                for d in range(k):
                    max_size = max(max_size, count_connected(grid, i, j, d))
            if grid[i][j] == '.' and i + k < n:
                for h in range(k):
                    max_size = max(max_size, count_connected(grid, i, j, h))
    print(max_size)

def count_connected(grid, start_i, start_j, offset):
    rows, cols = len(grid), len(grid[0])
    count = 1
    queue = [(start_i, start_j)]
    grid[start_i][start_j] = '#'
    while queue:
        i, j = queue.pop(0)
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di * offset, j + dj * offset
            if 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] == '.':
                count += 1
                grid[ni][nj] = '#'
                queue.append((ni, nj))
    return count

