def max_connected_component(n, k, grid):
    def dfs(r, c):
        if r < 0 or r >= n or c < 0 or c >= n or grid[r][c] == 'X':
            return 0
        grid[r][c] = 'X'  # Mark the cell as visited
        return 1 + dfs(r + 1, c) + dfs(r - 1, c) + dfs(r, c + 1) + dfs(r, c - 1)

    max_size = 0
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 'X':
                continue
            max_size = max(max_size, dfs(r, c))
